; DOS L preset: Conquests of Camelot (SCI0, DOS English 1.001.000), Korean
; UTF-8 translation (GAMES\CAMELKO: MESSAGE.MAP + RESOURCE.MSG, packed text
; resources + SCI-KO.STR, language=ko). KO2350.SVF (16 px, 1 bpp) beside this
; file; characters it lacks draw U+25A1. Every character this translation
; uses is in KS X 1001's 2350 Hangul, so nothing draws it (common2350-brief
; coverage gate, 2026-09-29).
;
; Canonical name: this replaces the camelot zip's own CAMKOL.MAP (same
; content, KO2350.SVF in place of the old per-game subset CAMKOL.SVF).
;
; Camelot's font ids, their line height in hi-res px and the game baseline
; (the game fonts are 8, 12 and 9 px tall, drawn at scale 2):
;   0    status/menu bar, parser line, title-menu buttons,   16
;        system dialogs
;   1    the title menu's label                              24
;   4    message boxes: narration, room descriptions,        18
;        dialogue, parser replies
;   103  intro narration over the pictures                   18
;   104  the same narration's outline passes (drawn under    18
;        103, several times, one game pixel apart)
; Font 104 uses CAMOUL.SVF, dilated by 2 px (1 game px) in a 20x20 cell from
; Camelot's own body glyphs (svfoutline.py - not in this tree; CAMOUL.SVF is
; kept as-is, copied through unchanged, since it already covers every
; character Camelot's body face draws): the narration's black outline.
[hires]
scale=2
alpha=false
face=ko
missing=u+25a1

[fonts]
ko=KO2350.SVF
out=CAMOUL.SVF

[latin]
mode=proportional
metrics=font

; 16 px lines: ink on rows 2-15 instead of 3-16
[font.0]
baseline=-1

[font.104]
face=out
